inline void load_one(const std::filesystem::path& path, const std::string& key) {
    std::ifstream ifs(path);
    if (!ifs) throw std::runtime_error("cannot open: " + path.string());
    nlohmann::json doc; ifs >> doc;

    SepConfig sep;
    if (doc.contains("_sep")) sep = sep_from_json(doc["_sep"]);

    const auto& data = doc["data"];

    auto tit = table_registry().find(key);
    if (tit != table_registry().end()) {
        std::vector<std::unordered_map<std::string, std::string>> rows;
        if (data.is_array()) {
            for (const auto& r : data) rows.push_back(json_obj_to_str_map(r));
        }
        tit->second(rows, sep);
        return;
    }

    auto cit = constant_registry().find(key);
    if (cit != constant_registry().end()) {
        cit->second(json_obj_to_str_map(data), sep);
        return;
    }
    // 未注册的文件，忽略
}

/// 加载 data_dir 下所有 .json，按 stem (去 .json 后缀) 匹配 registry。
inline void init_json(const std::string& data_dir) {
    namespace fs = std::filesystem;
    if (!fs::exists(data_dir)) throw std::runtime_error("data dir not found: " + data_dir);
    for (auto& e : fs::recursive_directory_iterator(data_dir)) {
        if (!e.is_regular_file()) continue;
        if (e.path().extension() != ".json") continue;
        auto rel = fs::relative(e.path(), data_dir);
        auto key = rel.replace_extension("").generic_string();
        load_one(e.path(), key);
    }
}

